import React, { useState, useEffect, useRef } from 'react';
import { MessageCircle, CheckCircle } from 'lucide-react';
import api from '../services/api';

export default function Mensagens() {
  const [notifs, setNotifs] = useState([]);
  const [loading, setLoading] = useState(true);
  const bottomRef = useRef(null);

  useEffect(() => {
    api.get('/notificacoes').then(res => setNotifs(res.data)).catch(() => {}).finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [notifs]);

  const marcarLida = (id) => {
    setNotifs(prev => prev.map(n => n.id === id ? { ...n, lida: true } : n));
    api.patch(`/notificacoes/${id}/lida`).catch(() => {});
  };

  if (loading) return <div className="loading"><div className="spinner" /></div>;

  const naoLidas = notifs.filter(n => !n.lida).length;

  return (
    <div className="page-container">
      <div className="page-header">
        <h2>Mensagens e Notificações</h2>
        <p>{naoLidas > 0 ? `${naoLidas} mensagem(ns) não lida(s)` : 'Todas as mensagens lidas'}</p>
      </div>

      <div className="card">
        {notifs.length === 0 ? (
          <div className="empty-state">
            <MessageCircle size={48} />
            <h3>Nenhuma mensagem ainda</h3>
            <p>As notificações da escola aparecerão aqui.</p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {notifs.map(n => (
              <div
                key={n.id}
                onClick={() => !n.lida && marcarLida(n.id)}
                style={{
                  display: 'flex', gap: 16, alignItems: 'flex-start',
                  padding: '1rem 1.25rem', borderRadius: 12,
                  background: n.lida ? 'var(--bege-claro)' : 'var(--laranja-suave)',
                  border: n.lida ? '1px solid var(--bege)' : '1px solid rgba(232,100,26,0.25)',
                  cursor: n.lida ? 'default' : 'pointer', transition: 'all 0.2s'
                }}
              >
                <div style={{ width: 42, height: 42, borderRadius: '50%', flexShrink: 0, background: n.lida ? 'var(--bege)' : 'var(--laranja)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <MessageCircle size={18} color={n.lida ? 'var(--cinza)' : 'white'} />
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8 }}>
                    <p style={{ fontSize: '0.9rem', fontWeight: n.lida ? 400 : 600, color: 'var(--castanho)', margin: 0 }}>{n.mensagem}</p>
                    {!n.lida && <span style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--laranja)', flexShrink: 0, marginTop: 4 }} />}
                  </div>
                  <div style={{ display: 'flex', gap: 12, marginTop: 6, alignItems: 'center' }}>
                    {n.criado_em && <span style={{ fontSize: '0.75rem', color: 'var(--cinza)' }}>{new Date(n.criado_em).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' })}</span>}
                    {n.tipo && <span style={{ fontSize: '0.72rem', fontWeight: 600, textTransform: 'uppercase', color: 'var(--castanho-claro)' }}>{n.tipo.replace('_',' ')}</span>}
                    {!n.lida && <span style={{ fontSize: '0.75rem', color: 'var(--laranja)', fontWeight: 600 }}>Clica para marcar como lida</span>}
                  </div>
                </div>
              </div>
            ))}
            <div ref={bottomRef} />
          </div>
        )}
      </div>
    </div>
  );
}
